const body = $json.body || {};
if (!body.name || (!body.email && !body.phone)) {
  throw new Error("Missing required lead fields: name, and at least one of email/phone");
}

return {
  json: {
    leadReceivedAtMs: Date.now(),
    name: body.name,
    email: body.email || "",
    phone: body.phone || "",
    companyName: body.companyName || "",
    companyWebsite: body.companyWebsite || "",
    serviceArea: body.serviceArea || "",
    buildingType: body.buildingType || "",
    sqft: body.sqft != null ? Number(body.sqft) : null,
    frequency: body.frequency || "",
    urgency: body.urgency || "",
    decisionRole: body.decisionRole || "",
    source: body.source || "",
    message: body.message || ""
  }
};

const markdown = ($json.data && $json.data.markdown) ? $json.data.markdown : "";
const lower = markdown.toLowerCase();

let enrichmentSignal = 0;
let enrichmentNote = "";

if (/current (cleaning|janitorial) (company|provider|vendor)|switch(ing)? (cleaning|janitorial) (company|provider)/.test(lower)) {
  enrichmentSignal = 5;
  enrichmentNote = "Company site suggests they may be switching cleaning providers";
} else if (markdown && (lower.includes("sq ft") || lower.includes("square feet") || lower.includes("sqft"))) {
  enrichmentSignal = 5;
  enrichmentNote = "Company site independently confirms a facility size mention";
}

const lead = $('Capture & Validate').item.json;
return {
  json: {
    ...lead,
    enrichmentSignal,
    enrichmentNote,
    firecrawlStatus: markdown ? "ok" : "empty"
  }
};

const lead = $('Capture & Validate').item.json;
return {
  json: {
    ...lead,
    enrichmentSignal: 0,
    enrichmentNote: "",
    firecrawlStatus: "skipped"
  }
};

// --- Buyer config: edit these for your business ---
const SERVICE_AREA_KEYWORDS = ["downtown", "midtown", "north side"]; // zips/cities/neighborhoods you service
const TARGET_BUILDING_TYPES = ["office", "medical", "retail", "warehouse"];
const MIN_SQFT_QUALIFIED = 3000;
const MID_SQFT_TIER = 1000;
const AUTO_BOOK_THRESHOLD = 75;
const HUMAN_REVIEW_MIN = 40;
const HUMAN_REVIEW_MAX = 65;
const SALES_EMAIL = "delivered@resend.dev";
const BOOKING_LINK = "https://cal.com/muhammad-ansar-lnji2j/30min";
// ----------------------------------------------------

const lead = $json;

// Spam/junk override -- still routed to a human, never silently discarded.
const msg = (lead.message || "").toLowerCase();
const isJunk = !lead.name || msg.includes("test test") || /^(asdf|xxx|n\/a)$/i.test((lead.name || "").trim());
if (isJunk) {
  return {
    json: {
      ...lead,
      score: 0,
      needsHumanReview: true,
      routeDecision: "human",
      scoreExplanation: "Flagged as likely spam or test data -- routed to a human to confirm rather than discarded.",
      responseTimeMs: Date.now() - lead.leadReceivedAtMs,
      salesEmail: SALES_EMAIL,
      bookingLink: BOOKING_LINK
    }
  };
}

let score = 0;
const reasons = [];

// 1. Service area
const area = (lead.serviceArea || "").toLowerCase();
if (area) {
  const inArea = SERVICE_AREA_KEYWORDS.some((k) => area.includes(k.toLowerCase()));
  if (inArea) { score += 20; reasons.push("in service area (+20)"); }
  else { reasons.push("service area not recognized (+0)"); }
} else {
  reasons.push("no service area given (+0)");
}

// 2. Building type
const btype = (lead.buildingType || "").toLowerCase();
if (TARGET_BUILDING_TYPES.some((t) => btype.includes(t))) { score += 15; reasons.push("target building type (+15)"); }
else if (btype) { score += 5; reasons.push("non-target but known building type (+5)"); }
else { reasons.push("building type unspecified (+0)"); }

// 3. Sqft tier
const sqft = lead.sqft;
if (sqft != null && sqft >= MIN_SQFT_QUALIFIED) { score += 20; reasons.push(`sqft ${sqft} meets ideal size (+20)`); }
else if (sqft != null && sqft >= MID_SQFT_TIER) { score += 10; reasons.push(`sqft ${sqft} mid-tier (+10)`); }
else { reasons.push("sqft too small or unspecified (+0)"); }

// 4. Frequency
const freq = (lead.frequency || "").toLowerCase();
if (freq.includes("week") || freq.includes("daily") || freq.includes("recurring")) { score += 15; reasons.push("recurring service requested (+15)"); }
else if (freq) { score += 5; reasons.push("one-time service requested (+5)"); }
else { reasons.push("frequency unspecified (+0)"); }

// 5. Urgency
const urgency = (lead.urgency || "").toLowerCase();
if (urgency.includes("asap") || urgency.includes("this week") || urgency.includes("immediate")) { score += 10; reasons.push("urgent timeline (+10)"); }
else if (urgency.includes("month")) { score += 5; reasons.push("within a month (+5)"); }
else { reasons.push("no urgency given / just researching (+0)"); }

// 6. Decision authority
const role = (lead.decisionRole || "").toLowerCase();
if (role.includes("owner") || role.includes("facilit") || role.includes("manager")) { score += 10; reasons.push("decision-maker role (+10)"); }
else { reasons.push("decision authority unknown (+0)"); }

// 7. Contact completeness
const hasValidContact = !!(lead.email || lead.phone);
if (lead.email && lead.phone) { score += 5; reasons.push("email + phone provided (+5)"); }

// 8. Enrichment signal (from Firecrawl, real site content -- not an AI guess)
if (lead.enrichmentSignal > 0) { score += lead.enrichmentSignal; reasons.push(`${lead.enrichmentNote} (+${lead.enrichmentSignal})`); }

// 9. Referral / existing customer source
const src = (lead.source || "").toLowerCase();
if (src.includes("referral") || src.includes("existing customer")) { score += 10; reasons.push("referral/existing customer source (+10)"); }

score = Math.max(0, Math.min(100, score));

const needsHumanReview = !hasValidContact || (score >= HUMAN_REVIEW_MIN && score <= HUMAN_REVIEW_MAX);
let routeDecision;
if (needsHumanReview) routeDecision = "human";
else if (score >= AUTO_BOOK_THRESHOLD) routeDecision = "book";
else routeDecision = "followup";

return {
  json: {
    ...lead,
    score,
    needsHumanReview,
    routeDecision,
    scoreExplanation: reasons.join("; "),
    responseTimeMs: Date.now() - lead.leadReceivedAtMs,
    salesEmail: SALES_EMAIL,
    bookingLink: BOOKING_LINK
  }
};

const lead = $('Score Lead').item.json;
return {
  json: {
    ...lead,
    airtableRecordId: $json.id || null
  }
};

