const reply = $json.candidates[0].content.parts[0].text.trim();
const lead = $('Merge CRM Result').item.json;
return {
  json: {
    ...lead,
    to: lead.email,
    subject: `Following up, ${lead.name}`,
    followUpText: reply
  }
};

const body = $json.body || {};
const payload = body.payload || {};
const attendee = (payload.attendees && payload.attendees[0]) || {};
const leadId = (payload.metadata && (payload.metadata.leadId || payload.metadata.leadid)) || null;

return {
  json: {
    airtableRecordId: leadId,
    attendeeEmail: attendee.email || "",
    attendeeName: attendee.name || "",
    bookingUid: payload.uid || "",
    startTime: payload.startTime || ""
  }
};

const records = $json.records || [];
if (records.length === 0) {
  throw new Error("No matching lead record found for booking confirmation email: " + $('Parse Cal.com Booking').item.json.attendeeEmail);
}
return {
  json: {
    ...($('Parse Cal.com Booking').item.json),
    airtableRecordId: records[0].id
  }
};
